------------ import ------------

------------ define ------------
local BasePath = "uiatlas/pvp/quizresults/%s.png"
local WaitForSeconds = Yielders.GetWaitForSeconds(1)
local StringToHash = Animator.StringToHash
local FirstAniHash = StringToHash("First")
local SecondAniHash = StringToHash("Second")
local NextAniHash = StringToHash("Next")
local WinAniHash = StringToHash("Win")
local LoseAniHash = StringToHash("Lose")
------------ define ------------

function PVPArenaQuizResultDialog:__init()
    self.isPlay = false
end

function PVPArenaQuizResultDialog:__delete()
    self.data = nil
end

function PVPArenaQuizResultDialog:Awake()
    UIEventProxy.Create(self.CloseLayer.gameObject).onPointerClick = Bind(self, self.OnClickCloseLayerAction)
    local pvpArenaDojo = pvpArenaComponent:GetPVPArenaDojo()
    self.matcherInfo   = pvpArenaDojo.matcherInfo
end
