function PVPArenaQuizResultDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local parameters = self.controller.Argument.parameters
        self.data       = parameters.data
        self.count      = #self.data
        self:ShowUI()

        self.__EventUpdateQuizResultAction = Events.AddListener(Constants.EventNames.PVPArenaUpdateQuizResult, Bind(self, self.OnEventUpdateQuizResultAction))
    end))
