end

function PVPArenaQuizResultDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.__EventUpdateQuizResultAction then
            Events.RemoveListener(Constants.EventNames.PVPArenaUpdateQuizResult, self.__EventUpdateQuizResultAction)
            self.__EventUpdateQuizResultAction = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
