function PVPArenaQuizResultDialog:ShowUI()
    self.isPlay = true
    cs_coroutine.start(function()
        while self.count > 0 do
            self:RefreshUI()
            cs_coroutine.yield_return(self.TitleGroup:WaitUntilAniCompleted())
            cs_coroutine.yield_return(self.PanelGroup:WaitUntilAniCompleted())
            if self.count > 0 then
                cs_coroutine.yield_return(WaitForSeconds)
            end
        end

        self.isPlay = false
    end)
end

function PVPArenaQuizResultDialog:RefreshUI()
    local count      = self.count
    local data       = self.data
    local panelAnimationNameConf = {
        [1] = FirstAniHash,
        [2] = SecondAniHash,
    }
    local animationName = panelAnimationNameConf[count] or NextAniHash
    if count >= 2 then
        local resultData = data[count - 1]
        self:RefreshImgCover(self.ImgCover2, resultData.isWin)
    end

    if count >= 3 then
        local resultData = data[count - 2]
        self:RefreshImgCover(self.ImgCover3, resultData.isWin)
    end

    local resultData  = data[count]
    local isWin       = resultData.isWin
    self:RefreshImgCover(self.ImgCover1, isWin)

    local titleAnimateName = isWin and WinAniHash or LoseAniHash
    self.TitleText.text = isWin and localize("恭喜获得") or localize("很遗憾")

    local playerId      = resultData.playerId
    local info          = self.matcherInfo[tostring(playerId)]
    self.TxtName.text   = info.name

    local wheel = resultData.wheel
    local matchChartTotalWheelNum = pvpArenaComponent:GetMatchChartTotalWheelNum()
    local isLastDisplayWheel = wheel == pvpArenaComponent:GetMatchChartTotalWheelNum()
    local tipText
    if isLastDisplayWheel then
        tipText = isWin and
                localize("获得   <color=#EB8446><size=36>冠军</size></color>") or
                localize("止步   <color=#EB8446><size=36>冠军赛</size></color>")
    else
        local text = wheel == (matchChartTotalWheelNum - 1) and localize("冠军赛") or localize("_num_强", 2^(matchChartTotalWheelNum - wheel + 1))
        tipText = isWin and
                localize("晋级   <color=#EB8446><size=36>_name_</size></color>", {_name_ = text}) or
                localize("止步   <color=#EB8446><size=36>_name_</size></color>", {_name_ = text})
    end

    self.TitleGroup:Play(titleAnimateName)
    self.PanelGroup:Play(animationName)
    table.remove(self.data)
    self.count = self.count - 1

    return titleAnimateName, animationName
end

---RefreshImgCover
---@param imageAlterable Engine.UI.ImageAlterable
function PVPArenaQuizResultDialog:RefreshImgCover(imageAlterable, isWin)
    imageAlterable:LoadSprite(string.format(BasePath, isWin and "pvp_massage_bg_win_02" or "pvp_massage_bg_lose_02"))
end

