function PVPArenaQuizResultDialog:OnClickCloseLayerAction()
    if self.isPlay then return end
    UIModule.BackDialog()
end

function PVPArenaQuizResultDialog:OnEventUpdateQuizResultAction(data)
    if self.data == nil then return end
    for i, v in ipairs(data) do
        table.insert(self.data, 1, v)
        self.count = self.count + 1
    end
end

---------------------------------------------------
--- handler end --
---------------------------------------------------

return PVPArenaQuizResultDialog